declare class CrossmintWallets {
    private readonly walletFactory;
    private constructor();
    /**
     * Initialize the Wallets SDK
     * @param crossmint - Crossmint data (use `createCrossmint` to initialize)
     * @returns A new CrossmintWallets instance
     */
    static from(crossmint: Crossmint): CrossmintWallets;
    /**
     * Get an existing wallet.
     * Works on both client and server side.
     * On client side, provide wallet args directly.
     * On server side, provide the wallet locator string and wallet args.
     * @param argsOrLocator - Wallet args (client) or wallet locator string (server)
     * @param maybeArgs - Wallet args (required when using wallet locator on server side)
     * @returns A wallet if found, throws WalletNotAvailableError if not found
     */
    getWallet<C extends Chain>(args: WalletArgsFor<C>): Promise<Wallet<C>>;
    getWallet<C extends Chain>(walletLocator: string, args: WalletArgsFor<C>): Promise<Wallet<C>>;
    /**
     * Create a new wallet.
     * Works on both client and server side.
     * Either a signer or recovery must be provided.
     * If no signer is provided but recovery is set, the wallet will be read-only.
     * @param options - Wallet creation options
     * @returns A new wallet
     */
    createWallet<C extends Chain>(options: WalletCreateArgs<C>): Promise<Wallet<C>>;
    createDeviceSigner(deviceKeyStorage: DeviceSignerKeyStorage, address?: string): Promise<DeviceSignerConfig>;
    createPasskeySigner(passkeyName: string): Promise<RegisterSignerPasskeyParams>;
}

export { CrossmintWallets };

type WalletCreateArgs<C extends Chain> = WalletArgsFor<C> & {
    /** Recovery signer for wallet creation. Device signers cannot be recovery signers. */
    recovery: Exclude<SignerConfigForChain<C>, DeviceSignerConfig>;
    /** Signers to register on the wallet during creation. */
    signers?: Array<SignerConfigForChain<C> | ExternalWalletRegistrationConfig>;
    alias?: string;
};
/**
 * A device signer descriptor containing the public key and locator.
 * Returned by `createDeviceSigner`.
 */
type DeviceSignerDescriptor = {
    type: "device";
    publicKey: {
        x: string;
        y: string;
    };
    locator: DeviceSignerLocator;
    name?: string;
};

type WalletArgsFor<C extends Chain> = {
    /** The blockchain to create the wallet on (e.g. "base-sepolia"). */
    chain: C;
    /** Optional owner identifier. */
    owner?: string;
    /** Optional array of wallet plugins. */
    plugins?: WalletPlugin<C>[];
    options?: WalletOptions;
    /** Optional wallet alias. */
    alias?: string;
};

type ServerSignerConfig = {
    type: "server";
    secret: string;
};
