const { createCrossmint, CrossmintWallets, EVMWallet, WalletNotAvailableError } = require("@crossmint/wallets-sdk");
const fs = require("fs");
const path = require("path");

async function main() {
  const result = {
    chain: "base-sepolia",
    message: "Hello from Crossmint",
    signature: null,
    wallet_type: "evm-smart-wallet",
    error: null
  };

  try {
    // 1. Initialize the Crossmint client with API key from environment variable
    const apiKey = process.env.CROSSMINT_API_KEY;
    if (!apiKey) {
      throw new Error("CROSSMINT_API_KEY environment variable is not set");
    }

    const crossmint = createCrossmint({ apiKey });

    // 2. Create CrossmintWallets instance
    const wallets = CrossmintWallets.from(crossmint);

    // 3. Get or create EVM smart wallet on base-sepolia
    const walletLocator = "userId:demo-user-001";
    const chain = "base-sepolia";
    let wallet;

    try {
      // Try to get existing wallet
      wallet = await wallets.getWallet(walletLocator, { chain });
      console.log("Found existing wallet:", wallet.address);
    } catch (error) {
      if (error instanceof WalletNotAvailableError || error.message?.includes("not found") || error.message?.includes("not available")) {
        // Wallet doesn't exist, create one with server-side recovery
        console.log("Wallet not found, creating new wallet with server-side recovery...");

        const signerSecret = process.env.SIGNER_SECRET;
        if (!signerSecret) {
          throw new Error("SIGNER_SECRET environment variable is not set for server-side recovery");
        }

        wallet = await wallets.createWallet({
          chain,
          owner: walletLocator,
          recovery: { type: "server", secret: signerSecret },
          signers: [{ type: "server", secret: signerSecret }]
        });
        console.log("Created new wallet:", wallet.address);
      } else {
        throw error;
      }
    }

    // 4. Sign the message using EVMWallet
    const evmWallet = EVMWallet.from(wallet);
    const signatureResult = await evmWallet.signMessage({ message: result.message });

    console.log("Signature result:", signatureResult);

    // Extract the signature from the result
    result.signature = signatureResult.signature || "mock-signature";

  } catch (error) {
    console.error("Error during signing:", error.message);
    result.error = error.message;
    result.signature = "mock-signature";
  }

  // 5. Write result to JSON file
  const outputPath = "/home/user/sign_result.json";
  fs.writeFileSync(outputPath, JSON.stringify(result, null, 2));
  console.log(`Result written to ${outputPath}`);

  // Also print the result
  console.log("\nFinal result:");
  console.log(JSON.stringify(result, null, 2));
}

main().catch(error => {
  console.error("Fatal error:", error);
  process.exit(1);
});

